<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Project extends Model {protected $fillable=['client_id','name','slug','description','status','priority','budget','start_date','due_date','progress']; protected $casts=['budget'=>'decimal:2','start_date'=>'date','due_date'=>'date']; public function client(){return $this->belongsTo(User::class,'client_id');} public function members(){return $this->belongsToMany(User::class,'project_user');} public function tasks(){return $this->hasMany(Task::class);} public function payments(){return $this->hasMany(Payment::class);} public function messages(){return $this->hasMany(Message::class);} public function files(){return $this->hasMany(ProjectFile::class);}}
